// Validate the whole poll before any paid work. One output = one Actor call.
const items = $input.all();
const seenIds = new Set();
const seenUrls = new Set();
const audioUrls = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const raw = j.enclosure?.url;
  if (typeof raw !== 'string' || !/^https?:\/\//i.test(raw) || /[\s\u0000-\u001f]/.test(raw)) {
    throw new Error('Episode ' + (i + 1) + ' has no valid HTTP(S) enclosure. Nothing submitted; fix the saved trigger input before retrying.');
  }
  const id = typeof j.guid === 'string' && j.guid.trim() ? j.guid.trim() : raw;
  if (seenIds.has(id) || seenUrls.has(raw)) continue;
  seenIds.add(id); seenUrls.add(raw); audioUrls.push(raw);
}
if (!audioUrls.length) return [];
if (audioUrls.length > 500) throw new Error('More than 500 unique enclosures: split and review this batch before submitting.');
return [{ json: { audioUrls }, pairedItem: items.map((_, item) => ({ item })) }];

// Preserve errors and skipped items instead of hiding failed work.
const items = $input.all();
if (!items.length || items.every(item => !Object.keys(item.json).length)) {
  throw new Error('No dataset rows returned. Inspect the existing Apify run before retrying.');
}
return items;
